<?php
require_once __DIR__.'/includes/functions.php';$items=db()->query("SELECT l.id,l.title,l.price,l.location,l.trust_status,l.fraud_score FROM listings l WHERE l.status='approved' ORDER BY l.created_at DESC LIMIT 24")->fetchAll();$pageTitle='Trust Radar';include __DIR__.'/includes/header.php';?><div class="section-head"><div><h2>Trust Radar</h2><p>Nearby-style risk visualization. Click a node card to open the listing.</p></div></div><div class="radar" style="height:520px"><?php foreach($items as $i=>$l):$angle=($i/max(count($items),1))*6.283;$r=18+($i%4)*9;$x=50+cos($angle)*$r;$y=50+sin($angle)*$r;?><a href="/listing.php?id=<?=$l['id']?>" title="<?=e($l['title'])?> · <?=money($l['price'])?> · <?=e(trust_label($l['trust_status']??''))?>" style="position:absolute;left:<?=$x?>%;top:<?=$y?>%;transform:translate(-50%,-50%);z-index:4"><span class="badge <?=e(trust_class($l['trust_status']??''))?>" style="box-shadow:var(--shadow)"><?=e($l['title'])?> · <?=e((string)round((float)$l['fraud_score']))?></span></a><?php endforeach;?></div><?php include __DIR__.'/includes/footer.php';?>